import{_ as l,a0 as n,w as d,s as p,I as i,x as e,a1 as o,A as r,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"gedit 深色模式下高亮文本不可見？以下是你能做的 | LCTT x X-CMD","titleTemplate":false,"description":"gedit 深色模式下高亮文本不可見？以下是你能做的 | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"gedit 深色模式下高亮文本不可見？以下是你能做的 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"gedit 深色模式下高亮文本不可見？以下是你能做的 | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20210120 Highlighted Text Not Visible in gedit in Dark Mode- Here-s What You Can Do","title":"gedit 深色模式下高亮文本不可見？以下是你能做的","tag":"202207","desc":""},"relativePath":"202207/20210120 Highlighted Text Not Visible in gedit in Dark Mode- Here-s What You Can Do.md","filePath":"[post].md"}'),g={name:"202207/20210120 Highlighted Text Not Visible in gedit in Dark Mode- Here-s What You Can Do.md"};function u(m,t,b,f,h,T){const s=n("Link");return d(),p("div",null,[t[24]||(t[24]=i("h1",{id:"gedit-深色模式下高亮文本不可見-以下是你能做的",tabindex:"-1"},[e("gedit 深色模式下高亮文本不可見？以下是你能做的 "),i("a",{class:"header-anchor",href:"#gedit-深色模式下高亮文本不可見-以下是你能做的","aria-label":"Permalink to “gedit 深色模式下高亮文本不可見？以下是你能做的”"},"​")],-1)),t[25]||(t[25]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202207/16/094145b0gdwez5zo0zyuhz.jpg",alt:""})],-1)),i("p",null,[t[1]||(t[1]=e("我喜歡 ",-1)),o(s,{href:"https://itsfoss.com/dark-mode-ubuntu/"},{default:r(()=>[...t[0]||(t[0]=[e("在 Ubuntu 中使用深色模式",-1)])]),_:1}),t[2]||(t[2]=e("。在我看來深色模式能夠緩解視覺疲勞，讓系統看起來更加的賞心悦目。",-1))]),i("p",null,[t[4]||(t[4]=e("我發現了一個 ",-1)),o(s,{href:"https://wiki.gnome.org/Apps/Gedit"},{default:r(()=>[...t[3]||(t[3]=[e("gedit",-1)])]),_:1}),t[5]||(t[5]=e(" 文本編輯器的小麻煩，如果你在深色模式下使用它，你也許也會遇到。",-1))]),t[26]||(t[26]=a('<p>默認情況下 gedit 高亮當前光標所在的行。這是一個非常有用的功能，但是如果你在 Linux 系統中開啓了深色模式，那麼你將會感到痛苦。為什麼？因為被高亮的文本將不再變得可讀。你自己看吧：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/01/gedit-dark-mode-problem.png?resize=779%2C367&amp;ssl=1" alt="Text on the highlighted line is hardly visible"></p><p>如果你選擇文本，它將變得可讀，但這並不是一個讓人感到有多麼愉快的閲讀或者編輯體驗。（LCTT 校注：在新的 Ubuntu 22.04 中，這一情況已經有所改善，“高亮當前行”已被取消勾選）</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/01/gedit-dark-mode-issue.png?resize=779%2C367&amp;ssl=1" alt="Selecting the text makes it better but that’s not a convenient thing to do for all lines"></p><p>好消息是你不需要再忍受它。我將演示幾個步驟讓你能夠同時享受 gedit 以及系統的深色模式。</p><h3 id="讓-gedit-在深色模式下閲讀體驗友好" tabindex="-1">讓 gedit 在深色模式下閲讀體驗友好 <a class="header-anchor" href="#讓-gedit-在深色模式下閲讀體驗友好" aria-label="Permalink to “讓 gedit 在深色模式下閲讀體驗友好”">​</a></h3><p>你基本上有兩個選擇：</p><ol><li>禁用高亮當前行，但也同時意味着你必須清楚地知道你在哪一行。</li><li>改變默認的顏色設置，但編輯器的顏色會變得稍微有些不同，而且如果你更改系統主題，它不會自動切換到淺色模式。</li></ol><p>在 gedit 或者 GNOME 的開發者解決這個問題之前，這是你必須要做的應變和妥協。</p><h4 id="選項1-禁止高亮當前行" tabindex="-1">選項1： 禁止高亮當前行 <a class="header-anchor" href="#選項1-禁止高亮當前行" aria-label="Permalink to “選項1： 禁止高亮當前行”">​</a></h4><p>當你打開 gedit 後，點擊漢堡菜單然後選擇“<ruby>首選項<rt>Preferences</rt></ruby>”。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/01/gedit-preference.jpg?resize=777%2C527&amp;ssl=1" alt="Go to Preferences"></p><p>在查看選項卡，你應該看到在 “<ruby>高亮<rt>Highlighting</rt></ruby>” 區域的下方的 “<ruby>高亮當前行<rt>Highlight current line</rt></ruby>” 選項。取消勾選這個選項，馬上就可以看到效果。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/01/disable-highlight-line-gedit.jpg?resize=781%2C530&amp;ssl=1" alt="Disable highlighting current line"></p><p>“高亮當前行”是一個有用的功能，如果你想繼續使用它，請選擇第二個選項。</p><h4 id="選項2-更改編輯器的顏色主題" tabindex="-1">選項2： 更改編輯器的顏色主題 <a class="header-anchor" href="#選項2-更改編輯器的顏色主題" aria-label="Permalink to “選項2： 更改編輯器的顏色主題”">​</a></h4><p>在“<ruby>首選項<rt>Preferences</rt></ruby>”窗口，找到 “<ruby>字體與顏色<rt>Font &amp; Colors</rt></ruby>” 標籤頁，然後將顏色主題更改為 “Oblivion”、“Solarized Dark”，或者 “Cobalt”。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/01/change-color-scheme-gedit.jpg?resize=785%2C539&amp;ssl=1" alt="Change the color scheme"></p><p>正如我前面所提到的，缺點就是當你把系統主題切換為淺色模式時，編輯器將不會自動切換到淺色模式。</p><h3 id="開發者應該修復的一個-bug" tabindex="-1">開發者應該修復的一個 bug <a class="header-anchor" href="#開發者應該修復的一個-bug" aria-label="Permalink to “開發者應該修復的一個 bug”">​</a></h3>',20)),i("p",null,[t[7]||(t[7]=e("這裏 ",-1)),o(s,{href:"https://itsfoss.com/best-modern-open-source-code-editors-for-linux/"},{default:r(()=>[...t[6]||(t[6]=[e("有幾個 Linux 可用的文本編輯器",-1)])]),_:1}),t[8]||(t[8]=e(" ，但是為了快速閲讀或編輯文本文件，我更推薦使用 gedit。儘管如此，小煩惱仍舊是小煩惱。開發者應該在將來的版本中為這個很好的文本編輯器修復這個問題，讓我們不再求助於這些應對辦法。",-1))]),t[27]||(t[27]=i("p",null,"你呢？你在你的系統上使用深色模式還是淺色模式？你注意到 gedit 的這個問題了嗎？你有使用什麼方法去解決它嗎？歡迎分享你的經驗。",-1)),t[28]||(t[28]=i("hr",null,null,-1)),i("p",null,[t[10]||(t[10]=e("via: ",-1)),o(s,{href:"https://itsfoss.com/gedit-dark-mode-problem/"},{default:r(()=>[...t[9]||(t[9]=[e("https://itsfoss.com/gedit-dark-mode-problem/",-1)])]),_:1})]),i("p",null,[t[15]||(t[15]=e("作者：",-1)),o(s,{href:"https://itsfoss.com/author/abhishek/"},{default:r(()=>[...t[11]||(t[11]=[e("Abhishek Prakash",-1)])]),_:1}),t[16]||(t[16]=e(" 選題：",-1)),o(s,{href:"https://github.com/lujun9972"},{default:r(()=>[...t[12]||(t[12]=[e("lujun9972",-1)])]),_:1}),t[17]||(t[17]=e(" 譯者：",-1)),o(s,{href:"https://github.com/void-mori"},{default:r(()=>[...t[13]||(t[13]=[e("void-mori",-1)])]),_:1}),t[18]||(t[18]=e(" 校對：",-1)),o(s,{href:"https://github.com/wxy"},{default:r(()=>[...t[14]||(t[14]=[e("wxy",-1)])]),_:1})]),i("p",null,[t[21]||(t[21]=e("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[19]||(t[19]=[e("LCTT",-1)])]),_:1}),t[22]||(t[22]=e(" 原創編譯，",-1)),o(s,{href:"https://linux.cn/"},{default:r(()=>[...t[20]||(t[20]=[e("Linux中國",-1)])]),_:1}),t[23]||(t[23]=e(" 榮譽推出",-1))])])}const w=l(g,[["render",u]]);export{k as __pageData,w as default};
